package hris_parser_test

import (
	"strings"
	"testing"

	hris_parser "github.com/dps-wmhris/backend/internal/modules/hris/application/parser"
)

func TestParseAttendanceCSV_FormatsClassificationAndMalformedDates(t *testing.T) {
	csvData := strings.Join([]string{
		"Report Title",
		"Period: 2026-01",
		"Generated By Machine",
		"\xef\xbb\xbfUser ID,Full Name,Date/Time",
		"10,andi,2026/01/05 08:05",
		"10,andi,2026/01/05 12:00",
		"10,andi,2026/01/05 12:45",
		"10,andi,2026/01/05 16:30",
		"10,andi,10/01/2026 14:15", // Saturday DD/MM/YYYY -> out (>= 14:00)
		"11,budi,2026/1/6 8:10",    // Single-digit month/day/hour
		"12,bad_date,abc/def/ghi xx:yy",
		"12,bad_rollover,2026-02-31 08:00",
	}, "\n")

	parsed, err := hris_parser.ParseAttendanceCSV(strings.NewReader(csvData), nil)
	if err != nil {
		t.Fatalf("ParseAttendanceCSV failed: %v", err)
	}

	andi, ok := parsed["10"]
	if !ok {
		t.Fatalf("expected user 10 to be parsed")
	}
	monLogs := andi.Days["2026-01-05"]
	if monLogs == nil || len(monLogs.Logs) != 4 {
		t.Fatalf("expected 4 punches on 2026-01-05, got %+v", monLogs)
	}
	wantTypes := []string{"in", "break-in", "break-out", "out"}
	for i, want := range wantTypes {
		if monLogs.Logs[i].LogType != want {
			t.Errorf("punch[%d]: want %s, got %s", i, want, monLogs.Logs[i].LogType)
		}
	}

	satLogs := andi.Days["2026-01-10"]
	if satLogs == nil || len(satLogs.Logs) != 1 || satLogs.Logs[0].LogType != "out" {
		t.Fatalf("expected Saturday 14:15 punch classified as out, got %+v", satLogs)
	}

	budi, ok := parsed["11"]
	if !ok || budi.Days["2026-01-06"] == nil {
		t.Fatalf("expected single-digit date 2026/1/6 to parse as 2026-01-06, got %+v", budi)
	}

	if _, exists := parsed["12"]; exists {
		t.Fatalf("expected malformed/rolled-over dates for user 12 to be skipped, got %+v", parsed["12"])
	}
}

func TestParseAttendanceCSV_ShortFileAndMissingColumns(t *testing.T) {
	if _, err := hris_parser.ParseAttendanceCSV(strings.NewReader("only\ntwo lines"), nil); err == nil {
		t.Fatalf("expected validation error for file with fewer than 4 lines")
	}

	missingCols := "meta1\nmeta2\nmeta3\nFull Name,Department\nandi,WMS\n"
	if _, err := hris_parser.ParseAttendanceCSV(strings.NewReader(missingCols), nil); err == nil {
		t.Fatalf("expected validation error when User ID / Date/Time columns are missing")
	}
}
